import gzip
import zlib
@pytest.mark.parametrize("encodings",[("gzip","deflate"),("deflate","gzip"),("gzip","deflate","gzip")])
def test_response_records(encodings):
    text="café line\n"*7
    wire=text.encode()
    for encoding in encodings:
        wire=gzip.compress(wire,mtime=0) if encoding=="gzip" else zlib.compress(wire)
    class Chunks(httpx.SyncByteStream):
        def __iter__(self):
            for offset in range(0,len(wire),5): yield wire[offset:offset+5]
    def handle(request):
        return httpx.Response(200,headers={"content-encoding":", ".join(encodings),"content-type":"text/plain; charset=utf-8"},stream=Chunks())
    with httpx.Client(transport=httpx.MockTransport(handle),trust_env=False) as client:
        with client.stream("GET","https://example.test/result") as response:
            assert "".join(response.iter_text(chunk_size=3)) == text
            assert response.num_bytes_downloaded == len(wire)

